UPDATE public.products SET
  specs = $t$[{"label":"Taille du boîtier","value":"44 mm"},{"label":"Écran","value":"1,47\" Super AMOLED, 480 x 480 px, verre saphir"},{"label":"Processeur","value":"Exynos W1000 (3 nm)"},{"label":"RAM","value":"2 Go"},{"label":"Stockage","value":"32 Go"},{"label":"Batterie","value":"435 mAh, charge sans fil"},{"label":"Connectivité","value":"Bluetooth 5.3, Wi-Fi, NFC, GPS"},{"label":"Capteurs","value":"BioActive (FC, ECG, BIA), SpO2, sommeil"},{"label":"Étanchéité","value":"5 ATM + IP68, MIL-STD-810H"},{"label":"Système","value":"Wear OS 6, One UI 8 Watch"},{"label":"Compatibilité","value":"Android (Samsung Galaxy recommandé), non compatible iOS"}]$t$::jsonb,
  description = $t$La Watch 8 44 mm allie un design sophistiqué à des capteurs de santé avancés pour un suivi quotidien précis. Son large écran offre une lisibilité optimale, idéale pour les professionnels et sportifs recherchant un accessoire high-tech performant au Cameroun.$t$,
  pros = ARRAY[$t$Écran Super AMOLED 1,47" lumineux sous verre saphir$t$, $t$Processeur Exynos W1000 3 nm très fluide$t$, $t$Suivi santé complet : ECG, composition corporelle, sommeil$t$]::text[],
  cons = ARRAY[$t$Autonomie d’environ 1 à 2 jours selon l’usage$t$, $t$Non compatible iPhone (Android uniquement)$t$]::text[],
  updated_at = now()
WHERE id = '95ceb23a-7b48-4f62-b969-c6f8529f2539'
  AND (specs IS DISTINCT FROM $t$[{"label":"Taille du boîtier","value":"44 mm"},{"label":"Écran","value":"1,47\" Super AMOLED, 480 x 480 px, verre saphir"},{"label":"Processeur","value":"Exynos W1000 (3 nm)"},{"label":"RAM","value":"2 Go"},{"label":"Stockage","value":"32 Go"},{"label":"Batterie","value":"435 mAh, charge sans fil"},{"label":"Connectivité","value":"Bluetooth 5.3, Wi-Fi, NFC, GPS"},{"label":"Capteurs","value":"BioActive (FC, ECG, BIA), SpO2, sommeil"},{"label":"Étanchéité","value":"5 ATM + IP68, MIL-STD-810H"},{"label":"Système","value":"Wear OS 6, One UI 8 Watch"},{"label":"Compatibilité","value":"Android (Samsung Galaxy recommandé), non compatible iOS"}]$t$::jsonb OR description IS DISTINCT FROM $t$La Watch 8 44 mm allie un design sophistiqué à des capteurs de santé avancés pour un suivi quotidien précis. Son large écran offre une lisibilité optimale, idéale pour les professionnels et sportifs recherchant un accessoire high-tech performant au Cameroun.$t$
       OR pros IS DISTINCT FROM ARRAY[$t$Écran Super AMOLED 1,47" lumineux sous verre saphir$t$, $t$Processeur Exynos W1000 3 nm très fluide$t$, $t$Suivi santé complet : ECG, composition corporelle, sommeil$t$]::text[] OR cons IS DISTINCT FROM ARRAY[$t$Autonomie d’environ 1 à 2 jours selon l’usage$t$, $t$Non compatible iPhone (Android uniquement)$t$]::text[]);

