UPDATE public.products SET
  specs = $t$[{"label":"Stockage","value":"128 Go"},{"label":"Origine","value":"US/Canada"},{"label":"Source","value":"MFOUNDI MALL - IPHONE"},{"label":"Écran","value":"6,1\" Liquid Retina LCD"},{"label":"Processeur","value":"A12 Bionic"},{"label":"RAM","value":"3 Go"},{"label":"Appareil photo principal","value":"12 MP (grand angle f/1.8)"},{"label":"Système d'exploitation","value":"iOS"},{"label":"Batterie","value":"2942 mAh"}]$t$::jsonb,
  description = $t$iPhone XR 128Go c’est le “bon plan” d’Apple : puce A12 Bionic + 3Go RAM, encore très rapide en 2026, iOS fluide, apps et jeux tournent sans lag même si c’est 1 génération avant l’A13. Stockage 128Go = ∼110Go utiles, t’es large pour 15 000 photos, apps et quelques vidéos 4K sans gérer la mémoire. Caméra simple 12MP grand angle f/1.8 avec mode portrait logiciel via 1 seul capteur, ça fait le taf jour/nuit mais pas d’ultra grand angle ni zoom optique. Écran LCD 6,1" Liquid Retina, moins contrasté que OLED mais grande dalle confort. $t$,
  pros = ARRAY[$t$Performances solides grâce à la puce A12 Bionic et 3Go de RAM, assurant une bonne fluidité pour apps et jeux.$t$, $t$128 Go de stockage offrent un espace confortable pour un grand nombre de photos, vidéos et applications.$t$, $t$Grand écran Liquid Retina de 6,1 pouces offrant un confort visuel appréciable.$t$]::text[],
  cons = ARRAY[$t$Appareil photo principal simple sans ultra grand angle ni zoom optique.$t$, $t$Écran LCD moins contrasté et avec des noirs moins profonds que les dalles OLED.$t$]::text[],
  updated_at = now()
