  description = $t$Le Samsung Galaxy S24 Ultra 256 Go est le flagship 2024 en titane : châssis titane et dos Gorilla Glass Victus 2, plus léger et plus solide que les S22/S23 Ultra. Écran Dynamic AMOLED 2X plat QHD+ de 6,8" à 120 Hz adaptatif, 2600 nits et traitement antireflet remarquable. Snapdragon 8 Gen 3 for Galaxy, 12 Go de RAM et Galaxy AI (traduction en direct, Circle to Search, retouche photo). Quadruple appareil photo 200 MP avec téléobjectifs x3 et x5, batterie 5000 mAh et S Pen intégré.$t$,
  pros = ARRAY[$t$Châssis titane ultra résistant et léger avec Gorilla Glass Victus 2$t$, $t$Appareil photo 200 MP avec zoom optique x5 et zoom spatial 100x$t$, $t$Galaxy AI intégrée : traduction en direct, Circle to Search, retouche photo intelligente$t$]::text[],
  cons = ARRAY[$t$Pas de slot microSD pour extension de stockage$t$, $t$Charge filaire limitée à 45W (concurrents proposent 65W+)$t$]::text[],
  updated_at = now()
WHERE id = '2358e474-5cbe-4638-af62-948370ae849f'
  AND (specs IS DISTINCT FROM $t$[{"label":"Stockage","value":"256 Go"},{"label":"Conditionnement","value":"Scellé"},{"label":"SIM","value":"SIM+eSIM"},{"label":"Origine","value":"Korea"},{"label":"Source","value":"SAMSUNG SCELLÉ SIM+eSIM"},{"label":"Écran","value":"6.8 pouces Dynamic AMOLED 2X 120Hz, 2600 nits"},{"label":"Processeur","value":"Snapdragon 8 Gen 3 for Galaxy"},{"label":"RAM","value":"12 Go"},{"label":"Appareil photo","value":"200 MP + 12 MP ultra grand-angle + 2 téléobjectifs (x3 et x5 optiques)"},{"label":"Batterie","value":"5000 mAh, charge 45W"},{"label":"Réseau","value":"5G"},{"label":"OS","value":"Android 14 avec One UI 6.1 et Galaxy AI"}]$t$::jsonb OR description IS DISTINCT FROM $t$Le Samsung Galaxy S24 Ultra 256 Go est le flagship 2024 en titane : châssis titane et dos Gorilla Glass Victus 2, plus léger et plus solide que les S22/S23 Ultra. Écran Dynamic AMOLED 2X plat QHD+ de 6,8" à 120 Hz adaptatif, 2600 nits et traitement antireflet remarquable. Snapdragon 8 Gen 3 for Galaxy, 12 Go de RAM et Galaxy AI (traduction en direct, Circle to Search, retouche photo). Quadruple appareil photo 200 MP avec téléobjectifs x3 et x5, batterie 5000 mAh et S Pen intégré.$t$
       OR pros IS DISTINCT FROM ARRAY[$t$Châssis titane ultra résistant et léger avec Gorilla Glass Victus 2$t$, $t$Appareil photo 200 MP avec zoom optique x5 et zoom spatial 100x$t$, $t$Galaxy AI intégrée : traduction en direct, Circle to Search, retouche photo intelligente$t$]::text[] OR cons IS DISTINCT FROM ARRAY[$t$Pas de slot microSD pour extension de stockage$t$, $t$Charge filaire limitée à 45W (concurrents proposent 65W+)$t$]::text[]);

UPDATE public.products SET
  specs = $t$[{"label":"Écran","value":"6.55 pouces AMOLED 90Hz"},{"label":"Processeur","value":"Qualcomm Snapdragon 778G 5G"},{"label":"Mémoire Vive","value":"8 Go RAM"},{"label":"Stockage","value":"128 Go ou 256 Go"},{"label":"Appareil Photo","value":"Triple capteur 64MP + 8MP + 5MP"},{"label":"Batterie","value":"4250 mAh avec charge rapide 33W"}]$t$::jsonb,
  description = $t$Le Xiaomi 11 Lite 5G NE est l’un des smartphones 5G les plus fins et légers : seulement 158 g pour 6,81 mm d’épaisseur. Son écran AMOLED 90 Hz compatible Dolby Vision affiche des couleurs éclatantes pour le streaming et le jeu, porté par un Snapdragon 778G 5G performant. Triple appareil photo 64 MP et batterie de 4250 mAh avec charge rapide 33 W.$t$,
  pros = ARRAY[$t$Design ultra-fin et poids plume exceptionnel$t$, $t$Superbe écran AMOLED 90Hz avec Dolby Vision$t$, $t$Processeur Snapdragon 778G très performant$t$]::text[],
  cons = ARRAY[$t$Capacité de batterie limitée par la finesse$t$, $t$Pas de prise jack 3.5mm$t$]::text[],
  updated_at = now()
WHERE id = '7b126a2e-8f52-4ded-83a2-68b39311c970'
  AND (specs IS DISTINCT FROM $t$[{"label":"Écran","value":"6.55 pouces AMOLED 90Hz"},{"label":"Processeur","value":"Qualcomm Snapdragon 778G 5G"},{"label":"Mémoire Vive","value":"8 Go RAM"},{"label":"Stockage","value":"128 Go ou 256 Go"},{"label":"Appareil Photo","value":"Triple capteur 64MP + 8MP + 5MP"},{"label":"Batterie","value":"4250 mAh avec charge rapide 33W"}]$t$::jsonb OR description IS DISTINCT FROM $t$Le Xiaomi 11 Lite 5G NE est l’un des smartphones 5G les plus fins et légers : seulement 158 g pour 6,81 mm d’épaisseur. Son écran AMOLED 90 Hz compatible Dolby Vision affiche des couleurs éclatantes pour le streaming et le jeu, porté par un Snapdragon 778G 5G performant. Triple appareil photo 64 MP et batterie de 4250 mAh avec charge rapide 33 W.$t$
       OR pros IS DISTINCT FROM ARRAY[$t$Design ultra-fin et poids plume exceptionnel$t$, $t$Superbe écran AMOLED 90Hz avec Dolby Vision$t$, $t$Processeur Snapdragon 778G très performant$t$]::text[] OR cons IS DISTINCT FROM ARRAY[$t$Capacité de batterie limitée par la finesse$t$, $t$Pas de prise jack 3.5mm$t$]::text[]);

UPDATE public.products SET
  specs = $t$[{"label":"Écran","value":"6.7 pouces HD+ 120Hz"},{"label":"Processeur","value":"MediaTek Helio G81"},{"label":"RAM","value":"4 Go"},{"label":"Stockage","value":"128 Go extensible microSD"},{"label":"Appareil photo","value":"50 MP arrière / 8 MP selfie"},{"label":"Batterie","value":"5160 mAh"},{"label":"SIM","value":"Double nano SIM"}]$t$::jsonb,
  description = $t$L’Infinix Hot 60i offre un grand écran de 6,7" à 120 Hz pour une navigation fluide, une batterie de 5160 mAh qui tient la journée et 128 Go de stockage extensibles par microSD. Processeur MediaTek Helio G81, 4 Go de RAM, appareil photo 50 MP et selfie 8 MP, double nano SIM : un smartphone complet à petit prix.$t$,
  pros = ARRAY[$t$Grand écran 120Hz$t$, $t$Autonomie 5160 mAh$t$, $t$Bon rapport qualité-prix$t$]::text[],
  cons = ARRAY[$t$Résolution HD+ seulement$t$, $t$4 Go RAM limite le multitâche$t$]::text[],
  updated_at = now()
WHERE id = 'add64d68-88e7-452f-bb2c-38630bcd9c3e'
  AND (specs IS DISTINCT FROM $t$[{"label":"Écran","value":"6.7 pouces HD+ 120Hz"},{"label":"Processeur","value":"MediaTek Helio G81"},{"label":"RAM","value":"4 Go"},{"label":"Stockage","value":"128 Go extensible microSD"},{"label":"Appareil photo","value":"50 MP arrière / 8 MP selfie"},{"label":"Batterie","value":"5160 mAh"},{"label":"SIM","value":"Double nano SIM"}]$t$::jsonb OR description IS DISTINCT FROM $t$L’Infinix Hot 60i offre un grand écran de 6,7" à 120 Hz pour une navigation fluide, une batterie de 5160 mAh qui tient la journée et 128 Go de stockage extensibles par microSD. Processeur MediaTek Helio G81, 4 Go de RAM, appareil photo 50 MP et selfie 8 MP, double nano SIM : un smartphone complet à petit prix.$t$
       OR pros IS DISTINCT FROM ARRAY[$t$Grand écran 120Hz$t$, $t$Autonomie 5160 mAh$t$, $t$Bon rapport qualité-prix$t$]::text[] OR cons IS DISTINCT FROM ARRAY[$t$Résolution HD+ seulement$t$, $t$4 Go RAM limite le multitâche$t$]::text[]);

UPDATE public.products SET
  specs = $t$[{"label":"Stockage","value":"512 Go"},{"label":"Conditionnement","value":"Scellé"},{"label":"SIM","value":"SIM+eSIM"},{"label":"Origine","value":"Korea"},{"label":"Source","value":"SAMSUNG SCELLÉ SIM+eSIM"},{"label":"Écran intérieur","value":"7.6 pouces Dynamic AMOLED 2X 120Hz"},{"label":"Écran extérieur","value":"6.2 pouces Dynamic AMOLED 120Hz"},{"label":"Processeur","value":"Snapdragon 8+ Gen 1 for Galaxy"},{"label":"RAM","value":"12 Go"},{"label":"Appareil photo","value":"50 MP + 12 MP ultra grand-angle + 10 MP téléobjectif x3 + 4 MP sous-écran"},{"label":"Batterie","value":"4400 mAh, charge 25W"}]$t$::jsonb,
  description = $t$Le Samsung Galaxy Z Fold4 réunit téléphone et tablette : écran externe Dynamic AMOLED 2X de 6,2" à 120 Hz pour l’usage courant et écran interne pliable de 7,6" à 120 Hz pour le multitâche sur trois applications. Snapdragon 8+ Gen 1, 12 Go de RAM et compatibilité S Pen. Triple appareil photo 50 MP + 12 MP ultra grand-angle + 10 MP téléobjectif x3, caméra sous l’écran interne. Batterie 4400 mAh avec charge 25 W pour une journée d’usage normal.$t$,
  pros = ARRAY[$t$Écran pliable 7,6 pouces idéal pour le multitâche et le divertissement$t$, $t$Appareil photo polyvalent avec zoom optique 3x et qualité Pro$t$, $t$Compatibilité S Pen intégrée pour la productivité$t$]::text[],
  cons = ARRAY[$t$Autonomie moyenne pour un usage intensif (charge 25W lente)$t$, $t$Prix élevé et fragilité relative de l'écran pliable$t$]::text[],
  updated_at = now()
WHERE id = '66c355a4-aad7-4925-913f-a46328f475a8'
  AND (specs IS DISTINCT FROM $t$[{"label":"Stockage","value":"512 Go"},{"label":"Conditionnement","value":"Scellé"},{"label":"SIM","value":"SIM+eSIM"},{"label":"Origine","value":"Korea"},{"label":"Source","value":"SAMSUNG SCELLÉ SIM+eSIM"},{"label":"Écran intérieur","value":"7.6 pouces Dynamic AMOLED 2X 120Hz"},{"label":"Écran extérieur","value":"6.2 pouces Dynamic AMOLED 120Hz"},{"label":"Processeur","value":"Snapdragon 8+ Gen 1 for Galaxy"},{"label":"RAM","value":"12 Go"},{"label":"Appareil photo","value":"50 MP + 12 MP ultra grand-angle + 10 MP téléobjectif x3 + 4 MP sous-écran"},{"label":"Batterie","value":"4400 mAh, charge 25W"}]$t$::jsonb OR description IS DISTINCT FROM $t$Le Samsung Galaxy Z Fold4 réunit téléphone et tablette : écran externe Dynamic AMOLED 2X de 6,2" à 120 Hz pour l’usage courant et écran interne pliable de 7,6" à 120 Hz pour le multitâche sur trois applications. Snapdragon 8+ Gen 1, 12 Go de RAM et compatibilité S Pen. Triple appareil photo 50 MP + 12 MP ultra grand-angle + 10 MP téléobjectif x3, caméra sous l’écran interne. Batterie 4400 mAh avec charge 25 W pour une journée d’usage normal.$t$
       OR pros IS DISTINCT FROM ARRAY[$t$Écran pliable 7,6 pouces idéal pour le multitâche et le divertissement$t$, $t$Appareil photo polyvalent avec zoom optique 3x et qualité Pro$t$, $t$Compatibilité S Pen intégrée pour la productivité$t$]::text[] OR cons IS DISTINCT FROM ARRAY[$t$Autonomie moyenne pour un usage intensif (charge 25W lente)$t$, $t$Prix élevé et fragilité relative de l'écran pliable$t$]::text[]);

UPDATE public.products SET
  specs = $t$[{"label":"Taille","value":"27 pouces"},{"label":"Résolution","value":"1920 x 1080 Full HD"},{"label":"Dalle","value":"IPS, angle 178°"},{"label":"Fréquence","value":"75 Hz"},{"label":"Connectique","value":"HDMI x2, VGA"},{"label":"Fonctions","value":"Filtre lumière bleue, sans scintillement"},{"label":"Poids","value":"3,2 kg"}]$t$::jsonb,
  description = $t$Le moniteur HP M27f offre une grande dalle IPS Full HD de 27" (1920 x 1080) à 75 Hz, avec des couleurs fidèles et un angle de vision de 178°. Son filtre de lumière bleue intégré préserve vos yeux sans altérer les couleurs, et sa connectique double HDMI + VGA s’adapte à votre PC, console ou ordinateur portable. Design fin à bords étroits, 3,2 kg.$t$,
  pros = ARRAY[$t$Dalle IPS couleurs fidèles$t$, $t$75Hz plus fluide que 60Hz$t$, $t$Connectique double HDMI$t$]::text[],
  cons = ARRAY[$t$Full HD seulement sur 27"$t$, $t$Pas USB-C$t$]::text[],
  updated_at = now()
WHERE id = '994068b8-83aa-4111-94cc-92c029b6dec0'
  AND (specs IS DISTINCT FROM $t$[{"label":"Taille","value":"27 pouces"},{"label":"Résolution","value":"1920 x 1080 Full HD"},{"label":"Dalle","value":"IPS, angle 178°"},{"label":"Fréquence","value":"75 Hz"},{"label":"Connectique","value":"HDMI x2, VGA"},{"label":"Fonctions","value":"Filtre lumière bleue, sans scintillement"},{"label":"Poids","value":"3,2 kg"}]$t$::jsonb OR description IS DISTINCT FROM $t$Le moniteur HP M27f offre une grande dalle IPS Full HD de 27" (1920 x 1080) à 75 Hz, avec des couleurs fidèles et un angle de vision de 178°. Son filtre de lumière bleue intégré préserve vos yeux sans altérer les couleurs, et sa connectique double HDMI + VGA s’adapte à votre PC, console ou ordinateur portable. Design fin à bords étroits, 3,2 kg.$t$
       OR pros IS DISTINCT FROM ARRAY[$t$Dalle IPS couleurs fidèles$t$, $t$75Hz plus fluide que 60Hz$t$, $t$Connectique double HDMI$t$]::text[] OR cons IS DISTINCT FROM ARRAY[$t$Full HD seulement sur 27"$t$, $t$Pas USB-C$t$]::text[]);

UPDATE public.products SET
  specs = $t$[{"label":"Puissance","value":"65 W"},{"label":"Connecteur","value":"USB-C (Type-C)"},{"label":"Entrée","value":"100-240V AC, 50-60 Hz"},{"label":"Sortie","value":"20V / 3.25A (65W PD)"},{"label":"Compatibilité","value":"PC portables Dell USB-C PD"},{"label":"Câble","value":"Câble secteur 2 broches inclus"}]$t$::jsonb,
  description = $t$L’adaptateur secteur Dell 65 W USB-C est un chargeur polyvalent conçu pour les ordinateurs portables et tablettes Dell compatibles USB-C Power Delivery. Il délivre jusqu’à 65 W (20 V / 3,25 A) via un connecteur USB-C réversible et est livré avec son câble d’alimentation secteur à 2 broches.$t$,
  pros = ARRAY[$t$Charge USB-C PD universelle 65W$t$, $t$Compact et fiable pour le bureau$t$, $t$Compatible large gamme Dell$t$]::text[],
  cons = ARRAY[$t$Vérifier compatibilité PD du PC$t$, $t$Un seul port USB-C$t$]::text[],
  updated_at = now()
WHERE id = '1567ff31-cad9-4dd2-8bab-99f6a3c1a8f0'
  AND (specs IS DISTINCT FROM $t$[{"label":"Puissance","value":"65 W"},{"label":"Connecteur","value":"USB-C (Type-C)"},{"label":"Entrée","value":"100-240V AC, 50-60 Hz"},{"label":"Sortie","value":"20V / 3.25A (65W PD)"},{"label":"Compatibilité","value":"PC portables Dell USB-C PD"},{"label":"Câble","value":"Câble secteur 2 broches inclus"}]$t$::jsonb OR description IS DISTINCT FROM $t$L’adaptateur secteur Dell 65 W USB-C est un chargeur polyvalent conçu pour les ordinateurs portables et tablettes Dell compatibles USB-C Power Delivery. Il délivre jusqu’à 65 W (20 V / 3,25 A) via un connecteur USB-C réversible et est livré avec son câble d’alimentation secteur à 2 broches.$t$
       OR pros IS DISTINCT FROM ARRAY[$t$Charge USB-C PD universelle 65W$t$, $t$Compact et fiable pour le bureau$t$, $t$Compatible large gamme Dell$t$]::text[] OR cons IS DISTINCT FROM ARRAY[$t$Vérifier compatibilité PD du PC$t$, $t$Un seul port USB-C$t$]::text[]);

UPDATE public.products SET
  specs = $t$[{"label":"Gamme","value":"ASUS ExpertBook P1"},{"label":"Écran","value":"FHD (1920 x 1080) avec bords fins NanoEdge"},{"label":"Stockage","value":"SSD PCIe NVMe haute performance"},{"label":"Sécurité","value":"Puce TPM 2.0 et encoche de sécurité"},{"label":"Clavier","value":"Chiclet avec course des touches optimisée"},{"label":"Poids","value":"Environ 1.5 kg à 1.8 kg selon la taille"}]$t$::jsonb,
  description = $t$L'ASUS ExpertBook P1 est un ordinateur portable conçu pour les professionnels et les étudiants exigeant une fiabilité quotidienne à un prix compétitif. Il allie un châssis robuste et élégant à des performances fluides pour assurer toutes vos tâches bureautiques et multimédias.$t$,
  pros = ARRAY[$t$Conception robuste et châssis renforcé$t$, $t$Écran NanoEdge avec traitement antireflet$t$, $t$Connectivité complète pour les périphériques pro$t$]::text[],
  cons = ARRAY[$t$Luminosité d'écran limitée en plein soleil$t$, $t$Autonomie variable selon l'usage intensif$t$]::text[],
  updated_at = now()
WHERE id = '8a14813c-e4e0-4ef5-9ff1-8c1f716d6585'
  AND (specs IS DISTINCT FROM $t$[{"label":"Gamme","value":"ASUS ExpertBook P1"},{"label":"Écran","value":"FHD (1920 x 1080) avec bords fins NanoEdge"},{"label":"Stockage","value":"SSD PCIe NVMe haute performance"},{"label":"Sécurité","value":"Puce TPM 2.0 et encoche de sécurité"},{"label":"Clavier","value":"Chiclet avec course des touches optimisée"},{"label":"Poids","value":"Environ 1.5 kg à 1.8 kg selon la taille"}]$t$::jsonb OR description IS DISTINCT FROM $t$L'ASUS ExpertBook P1 est un ordinateur portable conçu pour les professionnels et les étudiants exigeant une fiabilité quotidienne à un prix compétitif. Il allie un châssis robuste et élégant à des performances fluides pour assurer toutes vos tâches bureautiques et multimédias.$t$
       OR pros IS DISTINCT FROM ARRAY[$t$Conception robuste et châssis renforcé$t$, $t$Écran NanoEdge avec traitement antireflet$t$, $t$Connectivité complète pour les périphériques pro$t$]::text[] OR cons IS DISTINCT FROM ARRAY[$t$Luminosité d'écran limitée en plein soleil$t$, $t$Autonomie variable selon l'usage intensif$t$]::text[]);

COMMIT;
